refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.4.0

     DOMDocument::registerNodeClass
     ora ha un tipo di ritorno provvisorio true.

  &reftitle.examples;



    Aggiunta di un nuovo metodo a DOMElement per semplificare il codice


<?php

class myElement extends DOMElement {
   function appendElement($name) { 
      return $this->appendChild(new myElement($name));
   }
}

class myDocument extends DOMDocument {
   function setRoot($name) { 
      return $this->appendChild(new myElement($name));
   }
}

$doc = new myDocument();
$doc->registerNodeClass('DOMElement', 'myElement');

// D'ora in poi, aggiungere un elemento ad un altro costa solo una chiamata al metodo !
$root = $doc->setRoot('root');
$child = $root->appendElement('child');
$child->setAttribute('foo', 'bar');

echo $doc->saveXML();

?>


    &example.outputs;


<?xml version="1.0"?>
<root><child foo="bar"/></root>







    Recupero di elementi come classe personalizzata


<?php
class myElement extends DOMElement {
    public function __toString() {
        return $this->nodeValue;
    }
}

$doc = new DOMDocument;
$doc->loadXML("<root><element><child>text in child</child></element></root>");
$doc->registerNodeClass("DOMElement", "myElement");

$element = $doc->getElementsByTagName("child")->item(0);
var_dump(get_class($element));

// E approfitta del metodo __toString..
echo $element;
?>


    &example.outputs;


string(9) "myElement"
text in child







    Recupero del proprietario del documento


     Quando si crea un'istanza di un DOMDocument personalizzato, la
     proprietà ownerDocument farà riferimento alla classe
     istanziata. Tuttavia, se tutti i riferimenti a tale classe vengono rimossi, essa
     verrà distrutta e al suo posto verrà creato un nuovo DOMDocument.
     Per questo motivo si potrebbe utilizzare
     DOMDocument::registerNodeClass con
     DOMDocument



<?php
class MyDOMDocument extends DOMDocument {
}

class MyOtherDOMDocument extends DOMDocument {
}

// Crea MyDOMDocument con un po' di XML
$doc = new MyDOMDocument;
$doc->loadXML("<root><element><child>text in child</child></element></root>");

$child = $doc->getElementsByTagName("child")->item(0);

// L'attuale proprietario del nodo è MyDOMDocument
var_dump(get_class($child->ownerDocument));
// MyDOMDocument viene distrutto
unset($doc);
// E viene creata una nuova istanza di DOMDocument
var_dump(get_class($child->ownerDocument));

// Importa un nodo da MyDOMDocument
$newdoc = new MyOtherDOMDocument;
$child = $newdoc->importNode($child);

// Registra un DOMDocument personalizzato
$newdoc->registerNodeClass("DOMDocument", "MyOtherDOMDocument");

var_dump(get_class($child->ownerDocument));
unset($doc);
// Viene creato un nuovo MyOtherDOMDocument
var_dump(get_class($child->ownerDocument));
?>


    &example.outputs;


string(13) "MyDOMDocument"
string(11) "DOMDocument"
string(18) "MyOtherDOMDocument"
string(18) "MyOtherDOMDocument"







    Gli oggetti personalizzati sono transitori


      Gli oggetti delle classi di nodi registrate sono transitori, cioè vengono
      distrutti quando non sono più referenziati dal codice PHP e ricreati
      quando vengono recuperati nuovamente. Ciò implica che i valori delle proprietà personalizzate andranno
      persi dopo la ricreazione.




<?php
class MyDOMElement extends DOMElement
{
    public $myProp = 'valore predefinito';
}

$doc = new DOMDocument();
$doc->registerNodeClass('DOMElement', 'MyDOMElement');

$node = $doc->createElement('a');
$node->myProp = 'valore modificato';
$doc->appendChild($node);

echo $doc->childNodes[0]->myProp, PHP_EOL;
unset($node);
echo $doc->childNodes[0]->myProp, PHP_EOL;
?>

    &example.outputs;


valore modificato
valore predefinito
